package com.maakyuo.thorlauncher;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 final Handler handler=new Handler(Looper.getMainLooper());FrameLayout frame;GridLayout grid;ImageView background;boolean shown=false;long lastTap=0;int taps=0;final Runnable hide=()->setShown(false);
 @Override public void onCreate(Bundle b){super.onCreate(b);frame=new FrameLayout(this);background=new ImageView(this);background.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(background,new FrameLayout.LayoutParams(-1,-1));grid=new GridLayout(this);grid.setColumnCount(5);grid.setPadding(12,20,12,20);ScrollView scroll=new ScrollView(this);scroll.addView(grid);frame.addView(scroll,new FrameLayout.LayoutParams(-1,-1));grid.setTag(scroll);setContentView(frame);loadBackground();populate();setShown(false);
 frame.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_UP){long now=SystemClock.uptimeMillis();taps=now-lastTap<550?taps+1:1;lastTap=now;if(taps>=3){taps=0;setShown(!shown);}else if(shown)resetTimer();}return true;});
 background.setOnClickListener(v->tap());background.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_UP)tap();return true;});
 scroll.setOnTouchListener((v,e)->{if(shown)resetTimer();return false;});
 }
 void tap(){long now=SystemClock.uptimeMillis();taps=now-lastTap<550?taps+1:1;lastTap=now;if(taps>=3){taps=0;setShown(!shown);}}
 void setShown(boolean value){shown=value;View view=(View)grid.getTag();view.setVisibility(value?View.VISIBLE:View.GONE);handler.removeCallbacks(hide);if(value)resetTimer();}
 void resetTimer(){handler.removeCallbacks(hide);handler.postDelayed(hide,60000);}
 void loadBackground(){try{Uri uri=Uri.parse(getPreferences(0).getString("background",""));if(!uri.toString().isEmpty())background.setImageURI(uri);}catch(Exception ignored){}}
 void chooseBackground(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,42);}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==42&&res==RESULT_OK&&data!=null){Uri u=data.getData();if(u!=null){getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);getPreferences(0).edit().putString("background",u.toString()).apply();loadBackground();}}}
 void populate(){grid.removeAllViews();Button choose=new Button(this);choose.setText("배경 선택");GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.columnSpec=GridLayout.spec(0,5);grid.addView(choose,p);choose.setOnClickListener(v->{resetTimer();chooseBackground();});
 PackageManager pm=getPackageManager();Intent query=new Intent(Intent.ACTION_MAIN);query.addCategory(Intent.CATEGORY_LAUNCHER);java.util.List<ResolveInfo> apps=pm.queryIntentActivities(query,0);Collections.sort(apps,new ResolveInfo.DisplayNameComparator(pm));for(ResolveInfo info:apps){if(info.activityInfo.packageName.equals(getPackageName()))continue;LinearLayout cell=new LinearLayout(this);cell.setOrientation(1);cell.setGravity(Gravity.CENTER);ImageView icon=new ImageView(this);icon.setImageDrawable(info.loadIcon(pm));cell.addView(icon,new LinearLayout.LayoutParams(68,68));TextView label=new TextView(this);label.setText(info.loadLabel(pm));label.setTextSize(10);label.setMaxLines(2);label.setGravity(Gravity.CENTER);cell.addView(label);GridLayout.LayoutParams cp=new GridLayout.LayoutParams();cp.width=getResources().getDisplayMetrics().widthPixels/5-8;cp.height=110;grid.addView(cell,cp);cell.setOnClickListener(v->{resetTimer();Intent launch=new Intent(Intent.ACTION_MAIN);launch.addCategory(Intent.CATEGORY_LAUNCHER);launch.setClassName(info.activityInfo.packageName,info.activityInfo.name);launch.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);try{startActivity(launch);}catch(Exception e){Toast.makeText(this,"실행 실패",Toast.LENGTH_SHORT).show();}});}}
 @Override protected void onResume(){super.onResume();if(shown)resetTimer();}
 @Override protected void onDestroy(){handler.removeCallbacks(hide);super.onDestroy();}
}